checker_details.tests:
from solution import fit

def test_examples():
    assert fit('hello world', 8) == 'hello w…'
    assert fit('hello', 5) == 'hello'

def test_width1():
    assert fit('ab', 1) == '…'

def test_wide_boundary():
    assert fit('你好世界', 6) == '你好…'
    assert fit('你好世界', 5) == '你好…'
    assert fit('你好世界', 4) == '你…'

def test_wide_fits():
    assert fit('你好', 4) == '你好'

def test_combining_kept():
    assert fit('e\u0301e\u0301e\u0301', 2) == 'e\u0301…'

def test_combining_fits_total():
    assert fit('e\u0301e\u0301', 2) == 'e\u0301e\u0301'

def test_zwj():
    s = '👨\u200d👩'
    assert fit(s, 3) == '👨\u200d…'

def test_cut_together():
    assert fit('ab\u0301cd', 3) == 'ab\u0301…'

def test_fullwidth():
    assert fit('ＡＢＣ', 5) == 'ＡＢ…'

def test_empty():
    assert fit('', 1) == ''

def test_leading_mark_width1():
    assert fit('\u0301abc', 1) == '…'
